let requestController=new AbortController();
let user=null,configInfo={},routeVersion=0,cleanup=()=>{},cleanupNav=()=>{},activeBankroll=localStorage.getItem('activeBankroll')||'',toastTimer;
// In the iOS/Android apps the API lives on the hosted server (FF_API_BASE from config.js) and uses a bearer token.
const API_BASE=window.FF_API_BASE||'';
async function api(path,method='GET',data){const headers=method==='GET'?{}:{'Content-Type':'application/json'};const token=API_BASE&&localStorage.getItem('ff-token');if(token)headers.Authorization='Bearer '+token;const res=await fetch(API_BASE+path,{method,signal:requestController.signal,headers,body:method==='GET'?undefined:JSON.stringify(data||{})});const body=await res.json();if(API_BASE&&body&&body.token)localStorage.setItem('ff-token',body.token);if(API_BASE&&path==='/api/logout')localStorage.removeItem('ff-token');if(res.status===401&&user){user=null;go('/auth/login');}if(!res.ok)throw new Error(body.error||'Request failed.');return body;}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4500);}
const money=(n,currency='USD')=>new Intl.NumberFormat('en-US',{style:'currency',currency,maximumFractionDigits:2}).format(Number(n)||0);
const number=(n,d=1)=>new Intl.NumberFormat('en-US',{maximumFractionDigits:d}).format(n);
const empty=(title,text,action='')=>`<div class="empty">${icon('chart')}<h3>${title}</h3><p>${text}</p>${action}</div>`;
const button=(text,id,cls='primary')=>`<button class="${cls}" id="${id}">${text}</button>`;
function field(name,label,value='',type='text',extra=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function select(name,label,options,value){return `<div class="field"><label for="${name}">${label}</label><select name="${name}" id="${name}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`;}).join('')}</select></div>`;}
const textarea=(name,label,value='',extra='')=>`<div class="field"><label for="${name}">${label}</label><textarea id="${name}" name="${name}" ${extra}>${esc(value)}</textarea></div>`;
const formData=form=>Object.fromEntries(new FormData(form));
function modal(title,body,onSubmit,submitLabel='Save'){const el=$('#modal');el.innerHTML=`<div class="modal-head"><h2>${title}</h2><button type="button" class="ghost" data-close aria-label="Close dialog">${icon('close')}</button></div><form id="modal-form">${body}<p class="form-error" role="alert"></p><div class="modal-actions"><button type="button" data-close>Cancel</button><button class="primary" type="submit">${submitLabel}</button></div></form>`;$$('[data-close]',el).forEach(b=>b.onclick=()=>el.close());$('#modal-form').onsubmit=async e=>{e.preventDefault();const b=$('button[type=submit]',e.target);b.disabled=true;try{await onSubmit(formData(e.target));el.close();}catch(error){$('.form-error',el).textContent=error.message;}finally{b.disabled=false;}};el.showModal();}
function download(filename,text,type='text/csv'){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csv(rows){return rows.map(row=>row.map(x=>{let s=String(x??'');if(/^[=+@]/.test(s)||/^-\D/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}).join(',')).join('\r\n');}
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let ch=text[i];if(ch==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(ch===','&&!quoted){row.push(cell);cell='';}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(Boolean))rows.push(row);row=[];cell='';}else cell+=ch;}if(quoted)throw new Error('Unclosed quote in CSV.');row.push(cell);if(row.some(Boolean))rows.push(row);return rows;}
function chart(series,{labels=['Actual','EV'],height=240}={}){if(!series[0]?.length||(series[0].length===1&&series[0][0][0]===0))return empty('Your chart starts here','Add a session to see your results over time.');const all=series.flat().map(p=>p[1]);let min=Math.min(0,...all),max=Math.max(1,...all),range=max-min;const maxX=Math.max(1,...series.flat().map(p=>p[0]));const x=n=>45+n/maxX*695,y=n=>height-22-(n-min)/range*(height-45);const lines=[0,1,2,3,4].map(i=>{const value=min+range*i/4;return `<line x1="45" x2="750" y1="${y(value)}" y2="${y(value)}" stroke="#cabb9e" stroke-dasharray="3 5"/><text x="37" y="${y(value)+4}" text-anchor="end" fill="#73604e" font-size="10">${number(value,0)}</text>`;}).join('');return `<svg class="chart" viewBox="0 0 760 ${height}" role="img" aria-label="${esc(labels.join(' and '))} chart">${lines}${series.map((s,i)=>`<polyline points="${s.map(p=>`${x(p[0])},${y(p[1])}`).join(' ')}" fill="none" stroke="${i?'#69734a':'#a54c2d'}" stroke-width="2.5" ${i?'stroke-dasharray="5 4"':''}/>`).join('')}</svg><div class="chart-labels"><span>0</span><span>${number(maxX)} ${labels[0]==='Profit path'?'rounds':'hours'}</span></div><div class="legend">${labels.map((l,i)=>`<span><i style="background:${i?'#69734a':'#a54c2d'}"></i>${esc(l)}</span>`).join('')}</div>`;}
function localDate(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function sectionHead(tag,title,text){return `<div class="section-header"><span class="eyebrow">${tag}</span><h2>${title}</h2>${text?`<p>${text}</p>`:''}</div>`;}
function feature(title,text,ic='brain',key){return `<${key?'a':'div'} ${key?`href="${paths[key]}"`:''} class="panel feature">${icon(ic)}<h3>${title}</h3><p>${text}</p></${key?'a':'div'}>`;}
function authPage(mode){const signup=mode==='signup',forgot=mode==='forgot-password',reset=mode==='reset-password';const title=signup?'Create Your Account':forgot?'Reset Your Password':reset?'Choose a New Password':'Sign In to Your Account';$('#app').innerHTML=`<main id="main" class="auth-page"><div class="auth-wrap"><div class="auth-box"><div class="auth-top"><a href="/" class="back muted" aria-label="Back to home">←</a>${brand()}</div>${signup?'<p style="text-align:center"><span class="badge green">Free to start · 18+</span></p>':''}<h1>${title}</h1><form id="auth-form">${signup?field('username','Username','','text','required minlength="3" maxlength="30" autocomplete="username" placeholder="Choose a username"'):''}${!reset?field('email','Email Address','','email','required autocomplete="email" placeholder="you@example.com"'):''}${!forgot?`<div class="field"><div class="field-head"><label for="password">Password</label>${!signup&&!reset?'<a href="/auth/forgot-password">Forgot password?</a>':''}</div><div class="password-wrap"><input name="password" id="password" type="password" required ${signup||reset?'minlength="10"':''} maxlength="256" autocomplete="${signup||reset?'new-password':'current-password'}" placeholder="${signup||reset?'At least 10 characters':'••••••••'}"><button type="button" class="show-password" aria-label="Show password">${icon('eye')}</button></div></div>${signup||reset?field('confirm','Confirm Password','','password','required minlength="10" autocomplete="new-password"'):''}`:''}${signup?`<div class="field"><label for="au-birth">Birth year</label><select id="au-birth" name="birthYear" required><option value="">Select</option>${Array.from({length:83},(_,i)=>new Date().getFullYear()-18-i).map(y=>`<option>${y}</option>`).join('')}</select><small class="muted">Felt & Fortune is for adults 18 and older.</small></div>`:''}${signup?'<label class="check-label field"><input name="terms" type="checkbox" required><span>I agree to the <a href="/terms">Terms of Use</a> and <a href="/privacy">Privacy Policy</a>.</span></label>':''}<p class="form-error" role="alert"></p><button class="primary" type="submit">${signup?'Create Account':forgot?'Send Reset Link':reset?'Save New Password':'Sign In'} ${icon('arrow')}</button></form><p class="auth-foot">${signup?'Already have an account? <a href="/auth/login">Sign in</a>':forgot||reset?'<a href="/auth/login">Back to sign in</a>':'Don’t have an account? <a href="/start">Get started</a>'}</p></div><div class="auth-legal"><a href="/terms">Terms of Use</a> · <a href="/privacy">Privacy Policy</a></div></div></main>`;$('.show-password')?.addEventListener('click',e=>{const p=$('#password');p.type=p.type==='password'?'text':'password';e.currentTarget.setAttribute('aria-label',p.type==='text'?'Hide password':'Show password');});$('#auth-form').onsubmit=async e=>{e.preventDefault();const f=e.target;$('.form-error',f).textContent='';const data=formData(f);if((signup||reset)&&data.password!==data.confirm){$('.form-error',f).textContent='Passwords do not match.';return;}const b=$('button[type=submit]',f);b.disabled=true;try{if(reset)data.token=new URLSearchParams(location.search).get('token');const result=await api('/api/'+(mode==='login'?'login':mode),'POST',data);if(forgot){f.innerHTML='<div class="notice">If an account matches that email, a reset link has been sent.</div>';return;}if(reset){toast('Password updated. Please sign in.');go('/auth/login');return;}user=result.user;const next=sessionStorage.getItem('after-login');sessionStorage.removeItem('after-login');go(next&&(Object.values(paths).includes(next)||next.startsWith('/learn/lesson/'))?next:paths.learn);}catch(error){$('.form-error',f).textContent=error.message;}finally{b.disabled=false;}};}
function head(title,desc,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div>${actions}</div>`;}
const records=async(kind,parent='')=>(await api(`/api/records?kind=${kind}${parent?'&parent='+encodeURIComponent(parent):''}`)).records;
async function saveRecord(kind,body,parent,id){return api('/api/records'+(id?'/'+id:''),id?'PATCH':'POST',{kind,body,parent});}
function errorView(error){$('#page').innerHTML=head('Something went wrong','Your data has not been changed.')+`<div class="notice">${esc(error.message)}</div><button id="retry">Try again</button>`;$('#retry').onclick=()=>render();}
async function resultsPage(key){let [bankrolls,sessions]=await Promise.all([records('bankroll'),records('session')]);if(!bankrolls.some(b=>b.id===activeBankroll)){activeBankroll=bankrolls[0]?.id||'';}let days='All',game='All',trip='';function paint(){const bank=bankrolls.find(b=>b.id===activeBankroll),cur=bank?.body.currency||'USD';let filtered=sessions.filter(s=>s.parent===activeBankroll&&(game==='All'||s.body.game===game)&&(!trip||s.body.trip===trip)&&(days==='All'||Date.parse(s.body.date)>=Date.now()-Number(days)*86400000)).sort((a,b)=>a.body.date.localeCompare(b.body.date));let profit=0,ev=0,hours=0;const actual=[[0,0]],expected=[[0,0]];filtered.forEach(s=>{profit+=s.body.profit;ev+=s.body.ev;hours+=s.body.hours;actual.push([hours,profit]);expected.push([hours,ev]);});$('#page').innerHTML=head(names[key],key==='dashboard'?'Your performance at a glance.':'Log, organize, and explore every session.',`<button class="primary" id="new-session">${icon('plus')} Add Session</button>`)+(key==='dashboard'?`<section class="dashboard-tools" aria-label="Quick tools"><h2>Your next good habit.</h2>${toolTiles(true)}</section>`:'')+`<div class="toolbar"><select id="bank-select" aria-label="Bankroll">${bankrolls.map(b=>`<option value="${b.id}" ${b.id===activeBankroll?'selected':''}>${esc(b.body.name)} · ${esc(b.body.currency)}</option>`).join('')}</select><select id="game-filter" aria-label="Filter game">${['All',...new Set(sessions.map(s=>s.body.game))].map(g=>`<option ${game===g?'selected':''}>${esc(g)}</option>`).join('')}</select><select id="trip-filter" aria-label="Filter trip"><option value="">All trips</option>${[...new Set(sessions.map(s=>s.body.trip).filter(Boolean))].map(g=>`<option ${trip===g?'selected':''}>${esc(g)}</option>`).join('')}</select><div class="spacer"></div><button id="import">Import CSV</button><button id="export">${icon('download')} Export</button><button class="ghost small" id="template">CSV template</button></div><div class="panel mb">${chart([actual,expected])}<div class="toolbar" style="justify-content:center;margin-bottom:0"><div class="tabs">${[['1','24H'],['7','7D'],['30','30D'],['90','90D'],['365','1Y'],['All','All']].map(([v,l])=>`<button data-days="${v}" class="${days===v?'active':''}">${l}</button>`).join('')}</div></div></div><div class="metric-grid mb">${[['Total Profit',money(profit,cur),profit>=0?'positive':'negative'],['Sessions',filtered.length,''],['Hours',number(hours)+' h',''],['Avg / Hour',money(hours?profit/hours:0,cur),'']].map(([l,v,cls])=>`<div class="metric"><span class="label">${l}</span><span class="value ${cls}">${v}</span></div>`).join('')}</div><div class="panel"><div class="flex between mb"><h3 style="margin:0">${key==='dashboard'?'Recent Sessions':'Sessions'}</h3><span class="muted">EV ${money(ev,cur)}</span></div>${filtered.length?`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Game / Location</th><th>Hours</th><th>Profit</th><th>EV</th><th>Player</th><th></th></tr></thead><tbody>${filtered.slice().reverse().slice(0,key==='dashboard'?10:1000).map(s=>`<tr><td>${esc(s.body.date)}</td><td><strong>${esc(s.body.game)}</strong><br><small class="muted">${esc(s.body.location||'—')}</small></td><td>${number(s.body.hours)}</td><td class="${s.body.profit>=0?'positive':'negative'}">${money(s.body.profit,cur)}</td><td>${money(s.body.ev,cur)}</td><td>${esc(s.username)}</td><td><button class="small ghost" data-edit="${s.id}">View / Edit</button></td></tr>`).join('')}</tbody></table></div>`:empty('No sessions yet','Add your first session or import your existing results.')}<p class="field-hint">Figures use the selected bankroll’s currency. Different currencies are never combined.</p></div>`;
$('#bank-select').onchange=e=>{activeBankroll=e.target.value;localStorage.setItem('activeBankroll',activeBankroll);paint();};$('#game-filter').onchange=e=>{game=e.target.value;paint();};$('#trip-filter').onchange=e=>{trip=e.target.value;paint();};$$('[data-days]').forEach(b=>b.onclick=()=>{days=b.dataset.days;paint();});$('#new-session').onclick=()=>editSession();$$('[data-edit]').forEach(b=>b.onclick=()=>editSession(sessions.find(s=>s.id===b.dataset.edit)));
$('#export').onclick=()=>download('felt-and-fortune-sessions.csv',csv([['date','game','location','hours','profit','ev','notes','trip','fields'],...filtered.map(s=>['date','game','location','hours','profit','ev','notes','trip'].map(k=>s.body[k]).concat(JSON.stringify(s.body.fields||{})))]));$('#template').onclick=()=>download('session-template.csv',csv([['date','game','location','hours','profit','ev','notes','trip','fields'],['2026-01-01','Blackjack','Example venue',2,100,25,'Example only — replace before importing','Example trip','{}']]));$('#import').onclick=()=>importSessions();}
async function refresh(){sessions=await records('session');paint();}
function editSession(row){const b=row?.body||{date:localDate(),game:'Blackjack',hours:1,profit:0,ev:0};modal(row?'Session Details':'Add Session',`<div class="grid two">${field('date','Date',b.date,'date','required')}${field('game','Game',b.game,'text','required list="game-types"')}<datalist id="game-types"><option>Blackjack</option><option>Poker</option><option>Sports Betting</option></datalist>${field('location','Location',b.location)}${field('trip','Trip',b.trip)}${field('hours','Hours',b.hours,'number','required min="0" max="1000" step=".01"')}${field('profit','Profit / loss',b.profit,'number','required step=".01"')}${field('ev','Expected value',b.ev,'number','required step=".01"')}</div>${textarea('notes','Notes',b.notes)}${textarea('fields','Custom fields (JSON object)',JSON.stringify(b.fields||{}),'spellcheck="false"')}${row?`<button type="button" class="danger" id="delete-session">Delete Session</button>`:''}`,async data=>{let fields;try{fields=JSON.parse(data.fields);}catch{throw new Error('Custom fields must be a valid JSON object.');}if(!fields||Array.isArray(fields)||typeof fields!=='object')throw new Error('Custom fields must be an object.');await saveRecord('session',{...data,fields},row?.parent||activeBankroll,row?.id);await refresh();toast('Session saved.');});if(row)$('#delete-session').onclick=async()=>{if(!confirm('Delete this session? This cannot be undone.'))return;try{await api('/api/records/'+row.id,'DELETE');$('#modal').close();await refresh();toast('Session deleted.');}catch(e){$('.form-error',$('#modal')).textContent=e.message;}};}
function importSessions(){modal('Import Sessions',`<p>Import into the selected bankroll. Required columns: date, game, hours, profit, ev. Optional: location, notes, trip, fields.</p><div class="field"><label for="csv-file">CSV file</label><input type="file" id="csv-file" accept=".csv,text/csv" required></div><div id="csv-preview"></div>`,async()=>{if(!importRows.length)throw new Error('Select a valid CSV first.');let saved=0;try{for(const row of importRows){await saveRecord('session',row,activeBankroll);saved++;}}catch(e){importRows=importRows.slice(saved);await refresh();throw new Error(`${saved} saved; ${importRows.length} remain. ${e.message}`);}await refresh();toast(`${saved} sessions imported.`);});let importRows=[];$('#csv-file').onchange=async e=>{importRows=[];try{const file=e.target.files[0];if(file.size>2000000)throw new Error('Choose a file under 2 MB.');const rows=parseCSV(await file.text());const headers=rows.shift().map(h=>h.replace(/^\uFEFF/,'').trim().toLowerCase());for(const key of ['date','game','hours','profit','ev'])if(!headers.includes(key))throw new Error('Missing column: '+key);if(rows.length>1000)throw new Error('Import up to 1,000 sessions at a time.');importRows=rows.map((cells,index)=>{let body=Object.fromEntries(headers.map((h,i)=>[h,cells[i]||'']));for(const k of ['hours','profit','ev']){if(!body[k].trim()||!Number.isFinite(Number(body[k])))throw new Error(`Row ${index+2}: invalid ${k}.`);body[k]=Number(body[k]);}if(body.hours<0||body.hours>1000||!/^\d{4}-\d{2}-\d{2}$/.test(body.date)||!body.game)throw new Error(`Row ${index+2}: check date, game, and hours.`);body.fields=body.fields?JSON.parse(body.fields):{};return body;});$('#csv-preview').innerHTML=`<div class="notice">${importRows.length} sessions ready. Review the first five below, then save.</div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Game</th><th>Profit</th></tr></thead><tbody>${importRows.slice(0,5).map(r=>`<tr><td>${esc(r.date)}</td><td>${esc(r.game)}</td><td>${esc(r.profit)}</td></tr>`).join('')}</tbody></table></div>`;}catch(error){importRows=[];$('#csv-preview').innerHTML=`<p class="form-error">${esc(error.message)}</p>`;}};}
paint();}

async function bankrollPage(){const banks=await records('bankroll');const sessions=await records('session');$('#page').innerHTML=head('Bankrolls','Manage your funds, collaborators, and profit shares.',button(icon('plus')+' New Bankroll','new-bank'))+`<div class="grid two">${banks.map(b=>{let profit=sessions.filter(s=>s.parent===b.id).reduce((t,s)=>t+s.body.profit,0);return `<div class="panel"><div class="flex between"><h3>${esc(b.body.name)}</h3><span class="badge">${esc(b.body.type)}</span></div><div class="metric"><span class="label">Session profit</span><span class="value ${profit>=0?'positive':'negative'}">${money(profit,b.body.currency)}</span></div><div class="toolbar"><button data-manage="${b.id}">Manage</button><button data-open-bank="${b.id}" class="primary">View Results</button></div></div>`;}).join('')}</div>`;$('#new-bank').onclick=()=>modal('New Bankroll',field('name','Bankroll name','','text','required')+select('type','Type',['solo','team','friends'],'solo')+select('currency','Currency',['USD','EUR','GBP','CAD','AUD'],'USD')+field('initial','Starting bankroll',0,'number','min="0" step=".01" required'),async data=>{await saveRecord('bankroll',data);await bankrollPage();toast('Bankroll created.');});$$('[data-open-bank]').forEach(b=>b.onclick=()=>{activeBankroll=b.dataset.openBank;localStorage.setItem('activeBankroll',activeBankroll);go(paths.results);});$$('[data-manage]').forEach(b=>b.onclick=()=>manage(banks.find(x=>x.id===b.dataset.manage)));
async function manage(bank){try{const [m,contributions]=await Promise.all([api('/api/members?bankroll='+bank.id),records('contribution',bank.id)]);const owner=m.members.some(x=>x.user_id===user.id&&x.role==='owner');const profit=sessions.filter(s=>s.parent===bank.id).reduce((t,s)=>t+s.body.profit,0);const balance=bank.body.initial+profit+contributions.reduce((t,r)=>t+r.body.amount,0);modal(esc(bank.body.name),`<div class="metric mb"><span class="label">Balance including contributions</span><span class="value">${money(balance,bank.body.currency)}</span></div><h3>Members & profit allocation</h3><div class="table-wrap mb"><table><thead><tr><th>Player</th><th>Role</th><th>Share</th><th>Profit allocation</th><th></th></tr></thead><tbody>${m.members.map(x=>`<tr><td>${esc(x.username)}</td><td>${x.role}</td><td>${x.share}%</td><td>${money(profit*x.share/100,bank.body.currency)}</td><td>${owner&&x.role!=='owner'?`<button type="button" class="ghost small" data-remove-member="${esc(x.username)}">Remove</button>`:''}</td></tr>`).join('')}</tbody></table></div>${owner?`<h3>Add or update a member</h3><div class="grid two">${field('username','Existing username')}${select('role','Permission',[['viewer','View only'],['editor','Log own sessions']],'viewer')}${field('share','Profit share (%)',0,'number','min="0" max="100" step=".01"')}</div><p class="field-hint">Adding a member gives them access to this bankroll. The owner keeps the unallocated share.</p><button type="button" id="add-member">Add / Update Member</button><hr style="border-color:var(--border);margin:25px 0">${field('name','Bankroll name',bank.body.name,'text','required')}${field('initial','Starting bankroll',bank.body.initial,'number','min="0" step=".01"')}`:''}<h3 class="mt">Contributions & withdrawals</h3>${contributions.length?contributions.map(r=>`<p>${esc(r.username)} · ${money(r.body.amount,bank.body.currency)}<br><small>${esc(r.body.note)}</small></p>`).join(''):'<p>No contributions yet.</p>'}<div class="grid two">${field('amount','Amount (negative for withdrawal)',0,'number','step=".01"')}${field('note','Note')}</div><button type="button" id="add-contribution">Record Contribution</button>`,async data=>{if(owner)await saveRecord('bankroll',{...bank.body,name:data.name,initial:data.initial},null,bank.id);await bankrollPage();});$('#add-member')?.addEventListener('click',async()=>{try{const d=formData($('#modal-form'));await api('/api/members','POST',{bankroll:bank.id,username:d.username,role:d.role,share:d.share});$('#modal').close();await manage(bank);toast('Member access updated.');}catch(e){$('.form-error',$('#modal')).textContent=e.message;}});$$('[data-remove-member]').forEach(b=>b.onclick=async()=>{try{await api('/api/members','DELETE',{bankroll:bank.id,username:b.dataset.removeMember});$('#modal').close();await manage(bank);}catch(e){$('.form-error',$('#modal')).textContent=e.message;}});$('#add-contribution').onclick=async()=>{try{const d=formData($('#modal-form'));await saveRecord('contribution',{amount:d.amount,note:d.note},bank.id);$('#modal').close();await manage(bank);toast('Contribution saved.');}catch(e){$('.form-error',$('#modal')).textContent=e.message;}};}catch(e){toast(e.message);}}
}
async function forumPage(){const threads=await records('thread');const id=new URLSearchParams(location.search).get('thread');if(id){const thread=threads.find(t=>t.id===id);if(!thread){$('#page').innerHTML=empty('Thread not found','It may have been removed.',link('forum','Back to Forum','button'));return;}const replies=await records('reply',id);$('#page').innerHTML=head(esc(thread.body.title),`${esc(thread.body.category)} · Started by ${esc(thread.username)}`,link('forum','← All Discussions','button'))+`<article class="panel mb"><div class="flex mb"><span class="avatar">${esc(thread.username[0])}</span><strong>${esc(thread.username)}</strong><span class="muted">${new Date(thread.created*1000).toLocaleDateString()}</span></div><div class="post">${esc(thread.body.text)}</div>${thread.owner===user.id?'<button class="ghost small mt" id="edit-thread">Edit Thread</button>':''}</article><h3>${replies.length} Replies</h3>${replies.slice().reverse().map(r=>`<article class="panel mb"><div class="flex mb"><span class="avatar">${esc(r.username[0])}</span><strong>${esc(r.username)}</strong><small class="muted">${new Date(r.created*1000).toLocaleString()}</small></div><div class="post">${esc(r.body.text)}</div>${r.owner===user.id?`<button class="ghost small mt" data-edit-reply="${r.id}">Edit Reply</button>`:''}</article>`).join('')}<form id="reply-form" class="panel"><h3>Join the Discussion</h3>${textarea('text','Your reply','','required maxlength="10000"')}<p class="form-error" role="alert"></p><button class="primary">Post Reply</button></form>`;$('#reply-form').onsubmit=async e=>{e.preventDefault();try{await saveRecord('reply',formData(e.target),id);await forumPage();toast('Reply posted.');}catch(error){$('.form-error').textContent=error.message;}};$('#edit-thread')?.addEventListener('click',()=>editThread(thread));$$('[data-edit-reply]').forEach(b=>b.onclick=()=>{const r=replies.find(x=>x.id===b.dataset.editReply);modal('Edit Reply',textarea('text','Reply',r.body.text,'required maxlength="10000"'),async data=>{await saveRecord('reply',data,id,r.id);await forumPage();});});return;}
let category='All',search='';function paint(){const filtered=threads.filter(t=>(category==='All'||t.body.category===category)&&(`${t.body.title} ${t.body.text}`.toLowerCase().includes(search.toLowerCase())));$('#page').innerHTML=head('Forum','Strategy questions, trip reports, and conversations with other learners.',button(icon('plus')+' New Discussion','new-thread'))+`<div class="forum-guides">${[['Ask about a hand','Post the cards, the dealer’s upcard, the rules, and what you did. Others can explain the play.','Strategy'],['Share a trip report','Which casino, which table rules, the minimum, and how deep they dealt. No bragging about wins.','Trip Reports'],['Be kind and honest','No casino promotions, referral links, or claims of easy money. Report anything that breaks these rules.','General']].map(([t,d,cat])=>`<div class="forum-guide"><strong>${t}</strong><span>${d}</span><small>${cat}</small></div>`).join('')}</div>`+`<div class="toolbar"><input id="forum-search" type="search" placeholder="Search discussions…" aria-label="Search discussions" value="${esc(search)}"><select id="forum-category" aria-label="Category">${['All','Strategy','Trip Reports','Team Formation','General'].map(c=>`<option ${c===category?'selected':''}>${c}</option>`).join('')}</select></div><div class="panel" style="padding:0">${filtered.length?filtered.map(t=>`<a class="thread-item" href="${paths.forum}?thread=${t.id}"><span class="badge">${esc(t.body.category)}</span><h3>${esc(t.body.title)}</h3><small class="muted">${esc(t.username)} · ${new Date(t.created*1000).toLocaleDateString()}</small></a>`).join(''):empty('Start the Conversation','No discussions match this view. Create a thread to share a question or observation.')}</div>`;$('#new-thread').onclick=()=>editThread();$('#forum-category').onchange=e=>{category=e.target.value;paint();};$('#forum-search').onchange=e=>{search=e.target.value;paint();};}function editThread(row){const b=row?.body||{};modal(row?'Edit Discussion':'New Discussion',field('title','Title',b.title,'text','required maxlength="150"')+select('category','Category',['Strategy','Trip Reports','Team Formation','General'],b.category||'General')+textarea('text','Message',b.text,'required maxlength="20000"'),async data=>{const saved=await saveRecord('thread',data,null,row?.id);go(paths.forum+'?thread='+saved.record.id);toast('Discussion saved.');});}paint();}

async function messagesPage(){const result=await api('/api/messages');let selected=new URLSearchParams(location.search).get('to')||'';const namesList=[...new Set(result.messages.map(m=>m.sender===user.id?m.recipient_name:m.sender_name))];if(!selected)selected=namesList[0]||'';$('#page').innerHTML=head('Messages','Private conversations between you and another registered player.')+`<div class="panel"><div class="toolbar"><select id="conversation" aria-label="Conversation"><option value="">New conversation</option>${namesList.map(n=>`<option ${n===selected?'selected':''}>${esc(n)}</option>`).join('')}</select><button id="new-message">New Message</button></div><div class="message-list">${result.messages.filter(m=>m.sender_name===selected||m.recipient_name===selected).map(m=>`<div class="message ${m.sender===user.id?'mine':''}"><small>${esc(m.sender_name)} · ${new Date(m.created*1000).toLocaleString()}</small><p>${esc(m.body)}</p></div>`).join('')||empty('No Messages Yet','Use an existing player’s username to start a conversation.')}</div><form id="message-form" class="mt">${field('recipient','Recipient username',selected,'text','required maxlength="30"')}${textarea('text','Message','','required maxlength="10000"')}<p class="form-error" role="alert"></p><button class="primary">Send Message ${icon('arrow')}</button></form></div>`;$('#conversation').onchange=e=>go(paths.messages+'?to='+encodeURIComponent(e.target.value));$('#new-message').onclick=()=>{$('#recipient').value='';$('#recipient').focus();};$('#message-form').onsubmit=async e=>{e.preventDefault();const b=$('button',e.target);b.disabled=true;try{const d=formData(e.target);await api('/api/messages','POST',d);go(paths.messages+'?to='+encodeURIComponent(d.recipient));toast('Message sent.');}catch(error){$('.form-error').textContent=error.message;b.disabled=false;}};$('.message-list').scrollTop=$('.message-list').scrollHeight;}

async function directoryPage(){let casinos=await records('casino'),search='',heat='All',view='list';const id=new URLSearchParams(location.search).get('casino');const pre=new URLSearchParams(location.search).get('new');if(pre){setTimeout(()=>edit(null,{name:pre,city:new URLSearchParams(location.search).get('city')||''}),300);}if(id){const casino=casinos.find(c=>c.id===id);if(!casino){$('#page').innerHTML=empty('Game not found','This entry may have been removed.',link('directory','Back to Directory','button'));return;}const b=casino.body,reviews=await records('review',id);$('#page').innerHTML=head(esc(b.name),esc(b.city),link('directory','← Directory','button'))+`<div class="grid two"><div class="panel"><h3>Game Conditions</h3><div class="post">${esc(b.rules)}</div><div class="statline mt"><div><small class="muted">PENETRATION</small><strong>${b.penetration}%</strong></div><div><small class="muted">MINIMUM BET</small><strong>${money(b.minBet)}</strong></div><div><small class="muted">HEAT</small><strong>${esc(b.heat)}</strong></div></div><p class="mt post">${esc(b.notes)}</p><small class="muted">Reported by ${esc(casino.username)} · ${new Date(casino.updated*1000).toLocaleDateString()}</small>${casino.owner===user.id?'<div class="mt"><button id="edit-casino">Edit Entry</button></div>':''}</div><div class="panel"><h3>Community Reviews</h3>${reviews.map(r=>`<div class="mb"><strong>${esc(r.username)} · ${r.body.rating}/5</strong><p class="post">${esc(r.body.text)}</p></div>`).join('')||'<p>No reviews yet.</p>'}<button id="new-review" class="primary">Write Review</button></div></div><div class="notice">Conditions are submitted by players and can change. The report date and author are shown above.</div>`;$('#edit-casino')?.addEventListener('click',()=>edit(casino));$('#new-review').onclick=()=>modal('Write Review',select('rating','Rating',[1,2,3,4,5],5)+textarea('text','Your experience','','required maxlength="4000"'),async data=>{await saveRecord('review',data,id);await directoryPage();toast('Review saved.');});return;}
function paint(){const rows=casinos.filter(c=>`${c.body.name} ${c.body.city}`.toLowerCase().includes(search.toLowerCase())&&(heat==='All'||c.body.heat===heat));$('#page').innerHTML=head('Player Reports','What players saw at the table: conditions, heat, and reviews. Find curated rules on the '+link('casinos','Casino Map')+'.',button(icon('plus')+' Add Report','new-casino'))+`<div class="toolbar"><input id="directory-search" type="search" placeholder="Search casino or city…" value="${esc(search)}" aria-label="Search directory"><select id="heat-filter" aria-label="Heat level">${['All','Low','Moderate','High','Unknown'].map(h=>`<option ${h===heat?'selected':''}>${h}</option>`).join('')}</select><div class="spacer"></div><div class="tabs"><button data-view="list" class="${view==='list'?'active':''}">List</button><button data-view="map" class="${view==='map'?'active':''}">Map</button></div></div>${view==='map'?`<div class="map" role="region" aria-label="World coordinate map"><svg viewBox="0 0 720 360" preserveAspectRatio="none" aria-hidden="true">${Array.from({length:13},(_,i)=>`<path d="M${i*60} 0v360" stroke="#4c7286"/>`).join('')}${Array.from({length:7},(_,i)=>`<path d="M0 ${i*60}h720" stroke="#4c7286"/>`).join('')}<path d="M50 50l90-25 65 40-30 55-40 20 35 40-10 55-25 70-22-36-2-65-36-35-25-70ZM305 65l50-32 60 20 70-15 150 50-30 60-65-20-30 40-60-55-45 7 10 45-50 100-40-20-35-90 15-40ZM555 245l55-15 45 35-20 35-65-7Z" fill="#49706d"/></svg>${rows.map((c,i)=>`<button class="map-marker" data-marker="${c.id}" style="left:${(c.body.lng+180)/360*100}%;top:${(90-c.body.lat)/180*100}%" aria-label="${esc(c.body.name)}">${i+1}</button>`).join('')}</div><p class="field-hint">Schematic equirectangular world map. Marker positions use submitted latitude and longitude; land outlines are illustrative.</p>`:''}<div class="grid two mt">${rows.map(c=>`<a href="${paths.directory}?casino=${c.id}" class="panel"><div class="flex between"><h3>${esc(c.body.name)}</h3><span class="badge">${esc(c.body.heat)} heat</span></div><p>${esc(c.body.city)}</p><p>${esc(c.body.rules).slice(0,180)}</p><div class="flex between"><small class="muted">${c.body.penetration}% penetration · ${money(c.body.minBet)} min</small><small class="muted">${new Date(c.updated*1000).toLocaleDateString()}</small></div></a>`).join('')}</div>${!rows.length?`<div class="panel mt">${empty('No Game Reports Yet','Add a casino you know. This directory starts empty so every entry has a real contributor.')}</div>`:''}`;$('#new-casino').onclick=()=>edit();$('#directory-search').onchange=e=>{search=e.target.value;paint();};$('#heat-filter').onchange=e=>{heat=e.target.value;paint();};$$('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;paint();});$$('[data-marker]').forEach(b=>b.onclick=()=>go(paths.directory+'?casino='+b.dataset.marker));}
function edit(row,prefill){const b=row?.body||prefill||{};modal(row?'Edit Report':'Add a Player Report',field('name','Casino / game name',b.name,'text','required maxlength="120"')+field('city','City and country',b.city,'text','required maxlength="120"')+textarea('rules','Game rules',b.rules,'required maxlength="2000" placeholder="Decks, H17/S17, payout, surrender, DAS…"')+`<div class="grid two">${select('heat','Reported heat',['Unknown','Low','Moderate','High'],b.heat||'Unknown')}${field('penetration','Penetration (%)',b.penetration??75,'number','required min="0" max="100"')}${field('minBet','Minimum bet (USD)',b.minBet??25,'number','required min="0" step=".01"')}${field('lat','Latitude',b.lat??'','number','required min="-90" max="90" step="any"')}${field('lng','Longitude',b.lng??'','number','required min="-180" max="180" step="any"')}</div>`+textarea('notes','Notes',b.notes,'maxlength="4000"'),async data=>{await saveRecord('casino',data,null,row?.id);await directoryPage();toast('Game report saved.');});}paint();}
function passwordSettings(){
 const panel=document.createElement('form');panel.id='password-form';panel.className='panel mt';
 panel.innerHTML=`<h3>Change password</h3><div class="grid three">${field('current','Current password','','password','required autocomplete="current-password"')}${field('new-password','New password','','password','required minlength="10" maxlength="256" autocomplete="new-password"')}${field('confirm-password','Confirm new password','','password','required minlength="10" autocomplete="new-password"')}</div><p class="field-hint">Changing your password signs out your other sessions.</p><p class="form-error" role="alert"></p><button class="primary">Update Password</button>`;
 $('#page').append(panel);panel.onsubmit=async e=>{e.preventDefault();const d=formData(panel);const error=$('.form-error',panel);error.textContent='';if(d['new-password']!==d['confirm-password']){error.textContent='Passwords do not match.';return;}const b=$('button',panel);b.disabled=true;try{await api('/api/change-password','POST',{current:d.current,password:d['new-password']});panel.reset();toast('Password updated. Other sessions signed out.');}catch(e){error.textContent=e.message;}finally{b.disabled=false;}};
}
function legalPage(kind){const pages={"about": {"title": "Learn Blackjack the Right Way", "intro": "Felt & Fortune is a personalized blackjack course: short interactive lessons, seven focused practice tools, and a coach that adapts to what you already know.", "sections": [["What you get", "A placement quiz puts you on one of four tracks, from first hand to advantage play. Every answer is checked by our strategy engine, and checkpoints make sure a skill sticks before you move on."], ["How we make money", "Starting is free. Pro, an optional subscription, unlocks the full card-counting and advantage-play courses and unlimited practice. We don’t run ads, sell your data, take bets, or partner with casinos."], ["Honest about the odds", "Even perfect basic strategy leaves the house a small edge, and card counting is hard, slow, and not a reliable income for most people. We teach the math so you can make informed choices, including the choice not to play."]]}, "privacy": {"title": "Privacy Policy", "intro": "This describes what Felt & Fortune stores and why. The operator must add their legal name and contact details before public launch. [Operator: add contact email and postal address.]", "sections": [["Account data", "Your username, email address, birth year (to confirm you are 18 or older), and a salted scrypt password hash. A session cookie (or, in the apps, a sign-in token) keeps you signed in. Passwords are never stored in plain text."], ["Learning data", "Your plan and survey answers, lesson and practice results, chips, quests, cosmetics, streaks, and league standings, so the course can adapt to you."], ["Payments", "Subscriptions are processed by the App Store, Google Play, or our web payment provider. We store your plan, its status, and renewal dates, never your card number."], ["Email", "We send account and billing messages: receipts, trial-ending and renewal reminders, cancellation confirmations, and password resets."], ["Product analytics", "We record first-party events, such as starting the survey or starting a trial, to understand what works. We use no third-party trackers or advertising networks, and we don’t sell or share personal data."], ["Community", "Forum posts, player reports, reviews, and usernames on leaderboards are visible to other signed-in users. People who follow you can see your streak, this week’s XP, and your overall skill rating. Private messages are visible to their sender and recipient."], ["Your rights", "Download all your data or delete your account at any time from Profile → Your data. Deletion is permanent. Sessions expire after 14 days and reset links after 30 minutes."]]}, "terms": {"title": "Terms of Use", "intro": "Provisional terms. The operator must review and finalize them, including their legal identity and governing law, before charging customers. [Operator: finalize.]", "sections": [["Eligibility", "You must be 18 or older. Felt & Fortune is educational. It never accepts wagers or deposits, and chips have no cash value. You can earn them or buy them for cosmetics and power-ups, but they can never be wagered, sold, transferred, or exchanged for money or prizes."], ["Plans and billing", "The free plan includes the features on our pricing page. Pro is billed monthly ($9.99), or yearly ($79.99, with a 14-day free trial for new members). Trials convert to a paid plan unless canceled before they end; we email you 3 days before. Subscriptions renew automatically until canceled. Purchases are currently in test mode and nothing is charged."], ["Canceling and refunds", "Cancel any time in the Store (or in your App Store or Google Play settings for app purchases). Pro stays active until the end of the period you paid for. App store purchases are refunded under Apple’s and Google’s policies. [Operator: state the refund policy for web purchases, for example a 14-day refund window.]"], ["Your account", "Keep your password private and share only information you’re allowed to share. Don’t impersonate others, abuse community features, or try to access other people’s data. You can delete your account at any time."], ["Training and results", "Lessons, drills, and simulations are educational. Simulated results are estimates, not promises of financial results. Nothing here is gambling, financial, or legal advice. Casino rules shown on the map come from dated third-party sources and can change; confirm them at the table."]]}};const p=pages[kind];$('#app').innerHTML=navbar()+`<main id="main" class="legal-page"><a href="/">← Back to Home</a><h1 class="mt">${p.title}</h1><p>${p.intro}</p>${p.sections.map(([t,b])=>`<h2>${t}</h2><p>${b}</p>`).join('')}${kind==='about'?'<a class="button primary mt" href="/auth/signup">Create an Account →</a>':''}</main>`+footer();}
function go(url){history.pushState({},'',url);render();}
document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||a.target||a.download||a.hasAttribute('data-external'))return;const url=new URL(a.href,location.href);if(url.origin!==location.origin)return;e.preventDefault();if(url.pathname===location.pathname&&url.search===location.search&&url.hash){history.pushState({},'',url);document.getElementById(decodeURIComponent(url.hash.slice(1)))?.scrollIntoView({behavior:'smooth'});$('.navlinks')?.classList.remove('open');$('#nav-menu')?.setAttribute('aria-expanded','false');return;}go(url.pathname+url.search+url.hash);});
window.addEventListener('popstate',()=>render());
