function responsiblePage(){
 const pause=Number(localStorage.getItem('ff-break-until')||0),onBreak=pause>Date.now();
 $('#page').innerHTML=`<div class="responsible"><header class="page-hero"><div><h1>${g('shield')} Play responsibly</h1><p>Felt & Fortune teaches blackjack with play chips only. Nothing here can be wagered, won, or cashed out.</p></div></header>
  <div class="resp-grid">
   <section class="side-card"><h2>The honest math</h2><ul class="reasons">
    <li>${g('check')}<span>Even perfect basic strategy leaves the casino a small edge, usually 0.3% to 1% of every bet, and 6:5 payouts make it much worse.</span></li>
    <li>${g('check')}<span>Card counting can flip that edge to the player only by about 0.5% to 1.5%, with very large swings. Most people who try it do not make a reliable income.</span></li>
    <li>${g('check')}<span>Casinos may refuse to deal to counters. Using any device to count at a real table is illegal in many states.</span></li>
    <li>${g('check')}<span>Short-term results are mostly luck. Judge yourself by decisions, never by a winning or losing night.</span></li></ul></section>
   <section class="side-card"><h2>Signs to take a step back</h2><ul class="reasons">
    <li>${g('flame')}<span>Betting money you need for bills, or borrowing to play.</span></li>
    <li>${g('flame')}<span>Chasing losses, or playing longer and bigger to win it back.</span></li>
    <li>${g('flame')}<span>Hiding how much you play, or feeling restless when you try to stop.</span></li></ul>
    <p><strong>Free, confidential help, 24/7:</strong> call or text <b>1-800-GAMBLER</b> (1-800-426-2537), or visit the National Council on Problem Gambling at ncpgambling.org.</p></section>
   <section class="side-card"><h2>Take a break</h2><p class="muted">Pause reminders and hide the app's streak nudges for a while. Your progress and streak freezes stay safe.</p>
    ${onBreak?`<p><strong>You're on a break until ${new Date(pause).toLocaleDateString('en-US',{month:'long',day:'numeric'})}.</strong></p><button type="button" class="small" id="end-break">End break early</button>`:`<div class="flex">${[1,7,30].map(d=>`<button type="button" class="small" data-break="${d}">${d} day${d>1?'s':''}</button>`).join('')}</div>`}</section>
  </div></div>`;
 $$('[data-break]').forEach(b=>b.onclick=()=>{api('/api/prefs','POST',{breakDays:Number(b.dataset.break)}).catch(()=>{});localStorage.setItem('ff-break-until',String(Date.now()+Number(b.dataset.break)*86400000));toast('Break started. Take care of yourself.');responsiblePage();});
 $('#end-break')?.addEventListener('click',()=>{api('/api/prefs','POST',{breakDays:0}).catch(()=>{});localStorage.removeItem('ff-break-until');responsiblePage();});
}

function badgeShelf(b){if(!b)return '';const card=(x,locked)=>`<li class="badge-card t-${x.tier} ${locked?'locked':''}" role="button" tabindex="0" aria-haspopup="dialog" data-badge="${esc(x.name)}" data-how="${esc(x.desc)}" data-when="${locked?'':esc(x.earned||'')}" data-locked="${locked?1:0}"><span class="badge-medal">${g(locked?'lock':x.icon)}</span><strong>${esc(x.name)}</strong><small>${esc(locked?x.desc:x.tier==='event'?x.desc:x.earned?'Earned '+new Date(x.earned+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'')}</small></li>`;
 return `<section class="panel badge-panel"><div class="side-head"><h3>${g('trophy')} Badges</h3><span class="muted small">${b.earned.length} earned${b.events?` · ${b.events} event exclusive${b.events>1?'s':''}`:''}</span></div>${b.earned.length?`<ul class="badge-grid">${b.earned.map(x=>card(x,false)).join('')}</ul>`:'<p class="muted">Finish lessons, pass checkpoints, and complete monthly events to earn badges.</p>'}${b.locked.length?`<details class="badge-locked"><summary>${b.locked.length} more to earn</summary><ul class="badge-grid">${b.locked.map(x=>card(x,true)).join('')}</ul></details>`:''}</section>`;}
