const ctxBase={$,$$,esc,api,go,brand,paths,localDate,toast,getUser:()=>user,setUser:u=>{user=u;},onCleanup:fn=>{const prev=cleanup;cleanup=()=>{prev();fn();};}};
const learn=createLearn(ctxBase);
const practice=createPractice(ctxBase);
const simulator=createSimulator(ctxBase);
const casinoDirectory=createDirectory(ctxBase);
function needLogin(path){if(user)return false;sessionStorage.setItem('after-login',path);history.replaceState({},'','/auth/login');authPage('login');return true;}
function notFound(){$('#app').innerHTML=navbar()+`<main class="legal-page" id="main">${empty('Page not found','That page moved or doesn’t exist.',`<a class="button primary" href="${user?paths.learn:'/'}">${user?'Go to Learn':'Go home'}</a>`)}</main>`;}
async function render(){
 const version=++routeVersion;requestController.abort();requestController=new AbortController();cleanup();cleanupNav();cleanup=()=>{};cleanupNav=()=>{};if($('#modal').open)$('#modal').close();
 let path=location.pathname.replace(/\/$/,'')||'/';window.scrollTo(0,0);
 if(REDIRECTS[path]){history.replaceState({},'',REDIRECTS[path]+location.search);path=REDIRECTS[path];}
 const fail=error=>{if(version!==routeVersion)return;if($('#page'))errorView(error);else $('#app').innerHTML=navbar()+`<main class="legal-page" id="main">${empty('Something went wrong',esc(error.message),`<a class="button primary" href="${paths.learn}">Back to Learn</a>`)}</main>`;};
 try{
  if(path==='/'){if(user){history.replaceState({},'',paths.learn);return render();}homepage();return;}
  if(['/about','/privacy','/terms'].includes(path)){legalPage(path.slice(1));return;}
  if(path==='/start'){await learn.startPage();return;}
  if(path.startsWith('/certificate/')){await certificatePage(ctxBase,path.split('/')[2],navbar());return;}
  if(path.startsWith('/auth/')){const mode=path.split('/')[2];if(['login','forgot-password','reset-password'].includes(mode)){if(user&&mode==='login'){history.replaceState({},'',paths.learn);return render();}authPage(mode);return;}notFound();return;}
  if(needLogin(path))return;
  let m;
  if((m=path.match(/^\/learn\/lesson\/([a-z0-9-]+)$/))){await learn.lessonPage(m[1]);return;}
  if(path==='/tools/challenge'){await practice.challengePage();return;}
  if(path==='/tools/table'){await practice.tablePage();return;}
  if((m=path.match(/^\/tools\/(strategy|count|decks|truecount|index)$/))){await practice.toolPage(m[1]);return;}
  if(path==='/practice/weak'){await practice.toolPage('weak');return;}
  if(path==='/practice/drill'){await practice.toolPage('drill');return;}
  if(path==='/practice/workout'){await practice.toolPage('workout');return;}
  if(path==='/tools/testout'){await testoutPage(ctxBase);return;}
  if(path==='/tools/casino'){await casinoPage(ctxBase);return;}
  if(path==='/tools/backcount'){await backcountPage(ctxBase);return;}
  if(path==='/tools/rush'||path==='/tools/storm'){await rushPage(ctxBase,path.slice(7));return;}
  if((m=path.match(/^\/practice\/skill\/([a-z-]+)$/))){await practice.toolPage('skill-'+m[1]);return;}
  if(path==='/responsible'){appShell('profile');responsiblePage();return;}
  if(path==='/track'||path==='/track/bankrolls'){appShell('profile');withTabs([['/track','Sessions'],['/track/bankrolls','Bankrolls']],path);if(path==='/track')await resultsPage('results');else await bankrollPage();return;}
  const tab=path.split('/')[1];
  if(!TABS.some(t=>t[0]===tab)){notFound();return;}
  appShell(tab);
  if(path==='/learn')await learn.learnPage();
  else if(path==='/practice')await practice.hub();
  else if(path==='/tools')await practice.toolsHub();
  else if(path==='/tools/simulator'){if(await proOnly('simulator'))await simulator();}
  else if(path==='/tools/edge')await edgePage(ctxBase);
  else if(path==='/tools/builder')await builderPage(ctxBase);
  else if(path==='/tools/charts')chartsPage();
  else if(path==='/practice/daily')await dailyPage(ctxBase);
  else if(path==='/practice/report')await reportPage(ctxBase);
  else if(path==='/practice/review')await reviewPage(ctxBase);
  else if(path==='/practice/weakness')await weaknessPage(ctxBase);
  else if(path==='/track'||path==='/track/bankrolls'){withTabs([['/track','Sessions'],['/track/bankrolls','Bankrolls']],path);if(path==='/track')await resultsPage('results');else await bankrollPage();}
  else if(['/community','/community/directory','/community/reports','/community/messages','/community/friends'].includes(path)){withTabs([['/community','Forum'],['/community/friends','Friends'],['/community/directory','Casino Map ★'],['/community/messages','Messages']],path);if(path==='/community')await forumPage();else if(path==='/community/friends')await friendsPage(ctxBase);else if(path==='/community/directory'){if(await proOnly('map'))await casinoDirectory();}else if(path==='/community/reports')await directoryPage();else await messagesPage();}
  else if(path==='/store')await storePage(ctxBase);
  else if(path==='/quests'||path==='/quests/leaderboard')await questsPage(ctxBase);
  else if(path==='/profile')await profilePage();
  else notFound();
 }catch(error){fail(error);}
}
// Pro-only tools: free members see what the tool does and how to unlock it.
const PRO_PAGES={simulator:['chart','Bankroll Simulator','Model a game, bet spread, and bankroll over thousands of hours: expected win, swings, and risk of ruin before you risk a dollar.',['Expected value and hourly win rate','Standard deviation and N₀','Risk of ruin for your bankroll','Saved, shareable runs']],
 map:['pin','Casino Map','Every US blackjack casino on one map, with the rules, decks, and player reports that tell you which tables are worth your time.',['Rules and payouts by casino','Player reports on penetration and heat','Filter by state, rules, and minimums','Plan trips around good games']]};
async function proOnly(key){const eco=await loadEconomy(api,localDate);if(eco?.plan?.pro)return true;const [ic,title,text,perks]=PRO_PAGES[key];
 $('#page').innerHTML=`<section class="pro-gate"><div class="pro-gate-art">${g(ic)}<span class="pro-gate-crown">${g('crown')}</span></div><span class="pill">${g('crown')} Pro</span><h1>${title}</h1><p>${text}</p><ul class="pro-gate-list">${perks.map(p=>`<li>${g('check')}<span>${p}</span></li>`).join('')}</ul><div class="pro-gate-cta"><a class="button primary chunky" href="/store#plans">See Pro plans</a><button type="button" class="button ghost" id="pro-gate-more">What else is in Pro?</button></div></section>`;
 $('#pro-gate-more').onclick=()=>paywall({api},`${title} is part of Pro.`);return false;}
async function boot(){try{configInfo=await api('/api/me');user=configInfo.user;if(user)loadEconomy(api,localDate);}catch(error){toast('The server could not be reached. Reload to try again.');}await render();}
// Badges: tap one to see what it was earned for (one interaction that works on phones and computers alike).
function closeBadgePop(){$$('.badge-pop').forEach(p=>p.remove());}
function openBadgePop(el){closeBadgePop();const r=el.getBoundingClientRect(),locked=el.dataset.locked==='1',when=el.dataset.when;const pop=document.createElement('div');pop.className='badge-pop';pop.setAttribute('role','dialog');pop.setAttribute('aria-label',el.dataset.badge);
 pop.innerHTML=`<strong>${esc(el.dataset.badge)}</strong><p>${locked?'How to earn it: ':'Earned for: '}${esc(el.dataset.how)}</p>${!locked&&when?`<small>${new Date(when+'T12:00:00').toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})}</small>`:''}`;
 document.body.append(pop);const w=pop.offsetWidth;pop.style.left=Math.max(8,Math.min(innerWidth-w-8,r.left+r.width/2-w/2))+'px';pop.style.top=(r.bottom+window.scrollY+8)+'px';Sound.play('select');}
document.addEventListener('click',e=>{const b=e.target.closest('.badge-card');if(b){e.stopPropagation();if(document.querySelector('.badge-pop')&&b.dataset.open==='1'){b.dataset.open='';closeBadgePop();return;}$$('.badge-card').forEach(x=>x.dataset.open='');b.dataset.open='1';openBadgePop(b);return;}if(!e.target.closest('.badge-pop'))closeBadgePop();});
document.addEventListener('keydown',e=>{const b=e.target.closest?.('.badge-card');if(b&&(e.key==='Enter'||e.key===' ')){e.preventDefault();openBadgePop(b);}if(e.key==='Escape')closeBadgePop();});
window.addEventListener('popstate',closeBadgePop);
document.documentElement.classList.toggle('lefty',localStorage.getItem('ff-hand')==='left');fitCoachScreens();boot();
